stylesheet:
:root {
	--space-bg: #101417;
	--space-panel: #171c20;
	--space-panel-alt: #1d2328;
	--space-border: #2b333a;
	--space-text: #d2d7da;
	--space-muted: #8f999f;
	--space-accent: #5da9e9;
	--space-accent-hover: #83c3f5;
}

html {
	background: var(--space-bg);
}

body {
	background: var(--space-bg);
	color: var(--space-text);
	font-family: Arial, Helvetica, sans-serif;
	font-size: 13px;
}

a:link,
a:visited {
	color: var(--space-accent);
}

a:hover,
a:active {
	color: var(--space-accent-hover);
	text-decoration: none;
}

#container {
	min-width: 0;
	color: var(--space-text);
	font-family: inherit;
}

.wrapper {
	box-sizing: border-box;
	width: min(1180px, calc(100% - 32px));
	min-width: 0;
	max-width: none;
}

#logo {
	min-height: 150px;
	padding: 20px 0;
	background: #151a1f;
	border-bottom: 1px solid var(--space-border);
	display: flex;
	align-items: center;
}

#logo .wrapper {
	display: flex;
	align-items: center;
	justify-content: space-between;
	gap: 24px;
}

#logo img {
	display: block;
	max-width: min(100%, 420px);
	height: auto;
}

#logo ul.top_links {
	margin: 0;
	display: flex;
	flex-wrap: wrap;
	justify-content: flex-end;
	gap: 6px;
}

#header ul.menu li {
	margin: 0;
	display: block;
}

#header ul.menu li a {
	padding: 8px 10px 8px 30px;
	border-radius: 3px;
	color: #f4f6f7;
}

#header ul.menu li a:hover {
	background-color: rgba(255, 255, 255, 0.08);
}

#panel .upper {
	background: #0c0f11;
	border-color: #242a2f;
}

#panel .lower {
	background: var(--space-panel-alt);
	color: var(--space-muted);
	border-color: var(--space-border);
}

#panel .lower a:link,
#panel .lower a:visited,
#panel .lower a:hover,
#panel .lower a:active {
	color: var(--space-text);
}

#content {
	box-sizing: border-box;
	padding: 18px 0 28px;
	background: transparent;
}

.tborder {
	background: var(--space-panel);
	border: 1px solid var(--space-border);
	border-radius: 3px;
	box-shadow: 0 8px 24px rgba(0, 0, 0, 0.22);
	overflow: hidden;
}

.thead {
	background: #11161a;
	color: #fff;
	border-color: #050708;
}

.tcat {
	background: #252c31;
	color: #fff;
	border-color: #343d44 #161a1d #161a1d;
}

.trow1 {
	background: var(--space-panel);
	border-color: #22292e;
}

.trow2 {
	background: var(--space-panel-alt);
	border-color: #252d33;
}

table,
.smalltext {
	color: var(--space-text);
}

input.textbox,
textarea,
select {
	background: #0e1215;
	color: var(--space-text);
	border: 1px solid #39434a;
}

input.button,
button,
.button {
	background: #252d33;
	color: #fff;
	border: 1px solid #3a454d;
	border-radius: 3px;
}

#footer .upper {
	background: #111518;
	border-color: var(--space-border);
}

#footer .lower {
	background: #0c0f11;
	color: var(--space-muted);
}

#footer a:link,
#footer a:visited,
#footer a:hover,
#footer a:active {
	color: var(--space-text);
}

@media (max-width: 760px) {
	.wrapper {
		width: min(100% - 20px, 1180px);
	}

	#logo {
		min-height: 0;
	}

	#logo .wrapper {
		align-items: flex-start;
		flex-direction: column;
	}

	#logo ul.top_links {
		justify-content: flex-start;
	}
}
